/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for n in [1,7,8]:
    print('PAGE',n)
    def visit(resources,prefix=''):
        if resources is None: return
        xo=resources.get('/XObject',{})
        for name,ob in xo.items():
            o=ob.get_object()
            if o.get('/Subtype')=='/Image':
                print(prefix+name,o.get('/Width'),o.get('/Height'),o.get('/ColorSpace'),o.get('/Filter'))
            elif '/Resources' in o:
                visit(o['/Resources'],prefix+name+'/')
    visit(r.pages[n-1]['/Resources'])
